style.css:
/* Pinterest Garamond Theme */
* {
    font-family: Garamond, "EB Garamond", "Cormorant Garamond", serif !important;
}

/* Optional: make titles extra elegant */
h1, h2, h3,
[data-test-id="pinTitle"],
[data-test-id="board-name"] {
    font-family: "EB Garamond", Garamond, serif !important;
    letter-spacing: 0.5px;
}
/* Dark Vintage Pinterest Theme */
body {
    background: #111 !important;
    color: #d8d2c2 !important;
    font-family: Garamond, serif !important;
}

* {
    font-family: Garamond, serif !important;
}

div, header {
    background: #1a1a1a !important;
}

a {
    color: #c8b38a !important;
}
